ns {\n  opacity: 0;\n  transition: opacity .2s ease-in-out;\n}\n\n.wp-admin .alpaca-item:hover .alpaca-item-controls .dashicons {\n  opacity: .3;\n}\n\n.wp-admin .alpaca-item.is-watched .alpaca-item-controls .dashicons, .wp-admin .alpaca-item-dragging.is-watched .alpaca-item-controls .dashicons {\n  opacity: 1;\n}\n\n.wp-admin .alpaca-item .alpaca-item-controls .dashicons:hover {\n  cursor: pointer;\n}\n\n.wp-admin #alpaca-board .alpaca-item.is-filtered-out {\n  pointer-events: none;\n  display: none;\n}\n\n.wp-admin #alpaca-comments-wrapper #alpaca-comments-header {\n  order: 1;\n  padding: 8px 0;\n}\n\n.wp-admin #alpaca-comments {\n  flex-direction: column;\n  flex-grow: 1;\n  padding-top: 8px;\n  display: flex;\n}\n\n.wp-admin #alpaca-comments .alpaca-comments-timeline {\n  flex-direction: column;\n  display: flex;\n  position: relative;\n}\n\n.wp-admin #alpaca-comments .alpaca-comments-timeline .alpaca-timeline-item:last-child {\n  background: #fff;\n}\n\n.wp-admin #alpaca-comments .alpaca-comments-timeline:before {\n  content: \"\";\n  width: var(--timeline-width);\n  background-color: #ddd;\n  position: absolute;\n  top: 6px;\n  bottom: 18px;\n  left: 90px;\n}\n\n.wp-admin #alpaca-comments .alpaca-comment-form {\n  margin: 0 0 12px;\n}\n\n.wp-admin #alpaca-comments .alpaca-comment-form .alpaca-user {\n  top: -1px;\n}\n\n.wp-admin #alpaca-comments.oldestfirst, .wp-admin #alpaca-comments.oldestfirst .alpaca-comments-timeline {\n  flex-direction: column-reverse;\n}\n\n.wp-admin #alpaca-comments.oldestfirst .alpaca-comments-timeline .alpaca-timeline-item:first-child {\n  margin-bottom: 36px;\n}\n\n.wp-admin #alpaca-comments.oldestfirst .alpaca-comments-timeline .alpaca-timeline-item:last-child {\n  background: none;\n  margin-top: 0;\n}\n\n.wp-admin .alpaca-timeline-item[data-source=\"human\"] .alpaca-timeline-content, .wp-admin .alpaca-comment-form textarea {\n  background: #fff;\n  border: 1px solid #ddd;\n  border-radius: 8px;\n  flex-grow: 1;\n}\n\n.wp-admin .