ut {\n    margin: 5px -1px;\n  }\n\n  .wp-admin #alpaca-board .alpaca-container .alpaca-items {\n    overflow-y: auto;\n  }\n}\n\n@media (width <= 860px) {\n  .wp-admin #alpaca-board .alpaca-wrap {\n    flex-direction: column;\n  }\n\n  .wp-admin #alpaca-board .alpaca-container {\n    flex-direction: column;\n    width: calc(100% - 2em);\n    height: auto;\n    margin-top: 1em;\n    display: flex;\n    overflow-x: auto;\n  }\n\n  .wp-admin #alpaca-board .alpaca-container .alpaca-items {\n    flex-direction: row;\n    gap: .8ch;\n    display: flex;\n    overflow-x: auto;\n  }\n\n  .wp-admin #alpaca-board .alpaca-container .alpaca-items .alpaca-item {\n    flex-shrink: 0;\n    width: 200px;\n    height: 140px;\n  }\n\n  .wp-admin #alpaca-board .alpaca-container .alpaca-items .alpaca-item .alpaca-item-assignees[data-assignees=\"1\"] .alpaca-user .alpaca-user-name {\n    padding-left: 0;\n    display: none;\n  }\n\n  .wp-admin #alpaca-board .alpaca-container.hidden {\n    width: calc(100% - 2em);\n    padding: 0 10px;\n  }\n}\n/*# sourceMappingURL=index.css.map */\n","/* styles go here */\n\n$bgwhite: #fff;\n$greyborder: #ddd;\n$greyshade: #f0f0f0;\n$greytext: #999;\n$smallfont: 14px;\n$spacegap: 0.8ch;\n\n:root {\n  --timeline-width: 1px;\n}\n\n.timestamp {\n  white-space: nowrap;\n}\n\n.alpaca-issue-details {\n  p,\n  input,\n  textarea {\n    font-size: 15px;\n  }\n}\n\n.flexalign {\n  display: flex;\n  align-items: center;\n  gap: $spacegap;\n}\n\n.has-sidecontrols {\n  display: grid;\n  grid-template-columns: 1fr 100px;\n  grid-template-rows: 1fr;\n  gap: $spacegap;\n}\n.sidecontrols {\n  text-align: right;\n}\n\n.alpaca-wrap {\n  flex-wrap: nowrap;\n}\n\n.alpaca-empty-state {\n  margin: 2rem auto;\n  max-width: 600px;\n\n  .components-notice {\n    margin-bottom: 1rem;\n\n    p {\n      margin: 0.5rem 0;\n    }\n\n    strong {\n      font-size: 1.1em;\n    }\n\n    .components-button {\n      margin-top: 1rem;\n    }\n  }\n}\n\n.alpaca-modal {\n  background: $bgwhite;\n  color: inherit;\n\n  .small-wrapper {\n    padding: 0.8rem 0 1rem;\n  }\n\n  small {\n    font-size: 12px;\n  }\n\n  p {\n    margin-top: 0;\n    margin-bottom: 1rem;\n  }\n\n  button {\n    margin-right: 0.5rem;\n  }\n}\n\n.wp-admin {\n  &.post-type-issue {\n    .screenshot {\n      margin: 1rem 0 -1rem;\n\n      img {\n        max-width: 100%;\n        height: auto;\n      }\n    }\n  }\n\n  .alpaca-user {\n    img {\n      aspect-ratio: 1;\n      border-radius: 50%;\n      border: 1px solid $greyborder;\n      vertical-align: middle;\n      background: $bgwhite;\n      width: 20px;\n      height: 20px;\n    }\n  }\n\n  #alpaca-board-controls {\n    .alpaca-board-filter {\n      width: fit-content;\n      background: transparent;\n      border-width: 0;\n\n      & > div {\n        flex: none;\n      }\n\n      &:focus-within {\n        outline: none;\n        box-shadow: none;\n        border-width: 0;\n      }\n    }\n\n    .components-combobox-control {\n      width: 300px;\n    }\n  }\n\n  .alpaca-control-popover {\n    width: 300px;\n    padding: 8px 16px 16px;\n\n    .alpaca-control {\n      padding: 8px 0;\n    }\n\n    .components-menu-group {\n      border: none;\n    }\n\n    .components-menu-group__label {\n      margin: 0;\n    }\n  }\n\n  #alpaca-board {\n    .alpaca-wrap {\n      display: flex;\n    }\n\n    .alpaca-container {\n      margin: 0 10px 0 0;\n      padding: 0 10px 10px;\n      background: #f9f9f9;\n      border: 2px solid #e4e4e4;\n      border-radius: 4px;\n      display: flex;\n\n      .alpaca-container-header {\n        padding: 5px 0;\n        display: grid;\n        grid-template-columns: 1fr 40px;\n        align-items: center;\n\n        h2,\n        .alpaca-container-title-input input {\n          margin: 0;\n          font-size: 18px;\n          font-weight: 600;\n          padding: 0;\n          border: none;\n          background: transparent;\n\n          &:focus {\n            outline: none;\n            box-shadow: none;\n          }\n        }\n\n        .alpaca-container-title-input > div {\n          margin: -1px 0 0;\n          padding: 0;\n        }\n\n        .alpaca-item-count {\n          font-size: smaller;\n          font-weight: 200;\n          margin: 0.5rem;\n          opacity: 0.5;\n        }\n\n        .alpaca-container-controls {\n          padding: 2px 0;\n          flex-direction: row;\n\n          .components-button:focus:not(:disabled) {\n            box-shadow: none;\n          }\n\n          button {\n            margin-left: 2px;\n            opacity: 0.2;\n            transition: opacity 0.2s ease-in-out;\n\n            &:hover {\n              opacity: 1;\n              cursor: pointer;\n            }\n          }\n        }\n      }\n\n      &.hidden {\n        opacity: 0.5;\n\n        .alpaca-items {\n          display: none;\n        }\n      }\n    }\n\n    .alpaca-items {\n      padding: 0 2px;\n    }\n\n    .alpaca-item,\n    .alpaca-item-dragging {\n      display: flex;\n      flex-direction: column;\n      gap: $spacegap;\n      line-height: 2em;\n\n      .alpaca-item-upper {\n        display: grid;\n        grid-template-columns: 1fr 3em;\n        grid-template-rows: auto;\n        gap: 0;\n      }\n\n      transition: opacity 0.2s ease-in-out;\n      box-shadow: 0 0 2px #888;\n      border-radius: 8px;\n      padding: 8px 12px;\n      margin: 10px 0;\n      background-color: #fff;\n\n      .alpaca-item-deadline {\n        border-radius: 8px;\n      }\n\n      &.is-late {\n        .alpaca-item-deadline {\n          background-color: red;\n          color: white;\n          margin: 2px 0;\n          padding: 0 8px;\n        }\n      }\n\n      &[data-days-left='0'] {\n        .alpaca-item-deadline {\n          background-color: black;\n          color: white;\n          margin: 2px 0;\n          padding: 0 8px;\n        }\n      }\n\n      &[data-days-left='1'],\n      &[data-days-left='2'],\n      &[data-days-left='3'],\n      &[data-days-left='4'],\n      &[data-days-left='5'],\n      &[data-days-left='6'],\n      &[data-days-left='7'] {\n        .alpaca-item-deadline {\n          background-color: orange;\n          color: black;\n          margin: 2px 0;\n          padding: 0 8px;\n        }\n      }\n\n      .alpaca-item-content {\n        grid-column: 1;\n        grid-row: 1;\n        font-size: 15px;\n        line-height: 1.4;\n      }\n\n      .alpaca-item-controls {\n        grid-column: 2;\n        grid-row: 1;\n        text-align: right;\n      }\n\n      .alpaca-item-meta {\n        grid-column: 1;\n        grid-row: 2;\n        color: $greytext;\n        margin: 4px 0;\n        flex-wrap: wrap;\n\n        & > div {\n          display: flex;\n          align-items: center;\n          margin-right: 10px;\n        }\n\n        .alpaca-item-assignees {\n          .alpaca-user-name {\n            display: none;\n          }\n\n          &[data-assignees='1'] {\n            .alpaca-user .alpaca-user-name {\n              display: block;\n            }\n          }\n        }\n\n        .alpaca-item-icon {\n          text-wrap: nowrap;\n\n          svg {\n            margin-right: 3px;\n            vertical-align: middle;\n            margin-top: -2px;\n          }\n        }\n\n        .alpaca-user {\n          font-size: 0.8rem;\n          margin-left: -8px;\n\n          &:first-child {\n            margin-left: 0;\n          }\n        }\n      }\n    }\n\n    .alpaca-item-dragging {\n      cursor: grabbing;\n      transform: rotate(3deg);\n\n      // note: function to match admin colors in alpaca.php\n    }\n\n    .alpaca-item.empty {\n      font-style: italic;\n      background-color: transparent;\n      border: 1px dashed #aaa;\n\n      .alpaca-item-controls {\n        display: none;\n      }\n    }\n  }\n\n  .components-modal__frame.alpaca-details-modal {\n    position: absolute;\n    top: 0;\n    right: -8px;\n    max-width: 800px;\n    height: calc(100% - 32px);\n    margin: 32px 0 0 0;\n    animation: slide-in-right 300ms ease-out forwards;\n    transform-origin: 100% center; /* origin from right */\n  }\n\n  @keyframes slide-in-right {\n    from {\n      transform: translateX(100%);\n    }\n    to {\n      transform: translateX(0);\n    }\n  }\n\n  .alpaca-deadline-popover {\n    .components-popover__content {\n      padding: 1em;\n    }\n  }\n\n  .alpaca-issue-details {\n    .alpaca-issue-main {\n      h3 {\n        font-weight: bold;\n        font-size: xx-large;\n        line-height: 1.3;\n        margin: 5px 0;\n      }\n    }\n\n    .alpaca-issue-meta {\n      color: $greytext;\n      font-size: $smallfont;\n      line-height: 3em;\n      flex-direction: row;\n      gap: $spacegap;\n\n      .alpaca-user-name {\n        font-weight: 600;\n      }\n    }\n\n    table.alpaca-issue-details {\n      border: 0;\n      margin: 1em 0;\n      width: 100%;\n\n      th,\n      td {\n        font-size: 15px;\n        line-height: 1.8;\n        text-align: left;\n        vertical-align: top;\n      }\n\n      th {\n        padding: 5px 1rem 5px 0;\n        width: 150px;\n        font-weight: normal;\n      }\n\n      td {\n        padding: 5px 0;\n        word-break: break-all;\n      }\n\n      div {\n        margin: 0;\n        padding: 0;\n      }\n\n      input,\n      .alpaca-input,\n      .components-form-token-field__input-container,\n      .components-form-token-field__input-container .components-flex {\n        background: none;\n        border: none;\n        margin: 0;\n        padding: 0;\n        line-height: inherit;\n        min-height: auto;\n        font-size: 15px;\n      }\n\n      .components-form-token-field {\n        width: 100%;\n      }\n\n      .components-form-token-field__help {\n        display: none;\n      }\n\n      .components-form-token-field input,\n      .components-form-token-field:focus,\n      .components-form-token-field:focus-visible,\n      .components-form-token-field:focus-within {\n        outline: none !important;\n        box-shadow: none !important;\n        border: none !important;\n      }\n\n      .placeholder,\n      ::placeholder {\n        color: $greytext;\n      }\n    }\n\n    .components-tab-panel__tab-content {\n      // any tab styling\n      padding: 1em 0;\n    }\n\n    .alpaca-screenshot-wrapper {\n      position: relative;\n\n      .alpaca-screenshot {\n        width: 100%;\n        height: auto;\n      }\n\n      .alpaca-screenshot-delete {\n        position: absolute;\n        top: 0;\n        right: 0;\n      }\n    }\n\n    .components-panel {\n      margin-bottom: 1rem;\n\n      .alpaca-modal-textarea {\n        width: 100%;\n      }\n\n      textarea {\n        width: 100%;\n        font-family: monospace; /* Often good for preformatted text */\n        white-space: pre;\n        overflow: hidden scroll;\n      }\n    }\n  }\n\n  .alpaca-checklist-container {\n    .alpaca-checklist {\n      padding-bottom: 0.5rem;\n    }\n\n    padding: 1em 0;\n  }\n\n  .alpaca-checklist-item,\n  .alpaca-checklist-item--dragging {\n    display: flex;\n    align-items: center;\n\n    .components-base-control__field {\n      margin: 0;\n    }\n\n    input[type='text'] {\n      border-color: transparent;\n    }\n\n    .alpaca-textinput {\n      width: 100%;\n\n      input[type='text'] {\n        width: 100%;\n      }\n    }\n\n    &.checked {\n      input[type='text'] {\n        text-decoration: line-through;\n      }\n    }\n\n    &.active {\n      input[type='text'] {\n        border-color: inherit;\n      }\n    }\n\n    .alpaca-checklist-controls {\n      display: flex;\n      gap: 5px;\n    }\n\n    button {\n      padding: 0;\n      height: auto;\n      min-width: auto;\n    }\n  }\n\n  .alpaca-checklist-item--dragging {\n    z-index: 99900000 !important;\n    box-shadow: 0 4px 8px rgb(0 0 0 / 10%);\n  }\n\n  .alpaca-item .alpaca-item-controls .dashicons,\n  .alpaca-item-dragging .alpaca-item-controls .dashicons {\n    opacity: 0;\n    transition: opacity 0.2s ease-in-out;\n  }\n\n  .alpaca-item:hover .alpaca-item-controls .dashicons {\n    opacity: 0.3;\n  }\n\n  .alpaca-item.is-watched .alpaca-item-controls .dashicons,\n  .alpaca-item-dragging.is-watched .alpaca-item-controls .dashicons {\n    opacity: 1;\n  }\n\n  .alpaca-item .alpaca-item-controls .dashicons:hover {\n    cursor: pointer;\n  }\n\n  // fix: flash on star when you start dragging\n\n  #alpaca-board .alpaca-item.is-filtered-out {\n    display: none; // because there is a really weird bug arising when I use opacity\n    pointer-events: none;\n  }\n\n  #alpaca-comments-wrapper {\n    #alpaca-comments-header {\n      order: 1;\n      padding: 8px 0;\n    }\n  }\n\n  #alpaca-comments {\n    padding-top: 8px;\n    display: flex;\n    flex-direction: column;\n    flex-grow: 1;\n\n    .alpaca-comments-timeline {\n      position: relative;\n      display: flex;\n      flex-direction: column;\n\n      .alpaca-timeline-item:last-child {\n        background: $bgwhite;\n      }\n\n      &::before {\n        content: '';\n        position: absolute;\n        left: 90px; // Position of the vertical line\n        top: 6px;\n        bottom: 18px;\n        width: var(--timeline-width);\n        background-color: $greyborder; // Color of the timeline line\n      }\n    }\n\n    .alpaca-comment-form {\n      margin: 0 0 12px 0;\n      .alpaca-user {\n        top: -1px; // Needed, not sure why\n      }\n    }\n\n    &.oldestfirst {\n      flex-direction: column-reverse;\n\n      .alpaca-comments-timeline {\n        flex-direction: column-reverse;\n\n        .alpaca-timeline-item:first-child {\n          margin-bottom: 36px;\n        }\n\n        .alpaca-timeline-item:last-child {\n          background: none;\n          margin-top: 0;\n        }\n\n        &::before {\n        }\n      }\n    }\n  }\n\n  .alpaca-timeline-item[data-source='human'] .alpaca-timeline-content,\n  .alpaca-comment-form textarea {\n    flex-grow: 1;\n    border-radius: 8px;\n    background: $bgwhite;\n    border: 1px solid $greyborder;\n  }\n\n  .alpaca-comment-form,\n  .alpaca-timeline-item {\n    position: relative;\n    display: flex;\n  }\n\n  .alpaca-comment-form,\n  .alpaca-timeline-item {\n    font-size: 15px;\n\n    .alpaca-timeline-content,\n    textarea {\n      width: 100%;\n    }\n\n    .alpaca-user {\n      position: absolute;\n    }\n\n    .alpaca-comment-buttons {\n      display: flex;\n      margin-left: auto;\n      opacity: 0;\n      transition: opacity 0.2s ease-in-out;\n      position: absolute;\n      top: 0;\n      right: 0;\n    }\n\n    &[data-source='human'] {\n      padding-left: 72px;\n\n      .alpaca-user {\n        left: 10px;\n\n        img {\n          width: 36px;\n          height: 36px;\n        }\n\n        .alpaca-user-name {\n          display: none;\n        }\n      }\n\n      .alpaca-comment-header {\n        display: flex;\n        padding-left: 18px;\n        background: $greyshade;\n        border-top-left-radius: 8px;\n        border-top-right-radius: 8px;\n        border-bottom: 1px solid $greyborder;\n        font-size: $smallfont;\n        line-height: 32px;\n      }\n\n      .alpaca-timeline-content {\n        flex-grow: 1;\n      }\n\n      .alpaca-comment-content {\n        padding: 1em 15px 0 15px;\n\n        blockquote {\n          background: $greyshade;\n          padding: 1.5em 0.5em 0.5em 1.5em;\n          margin: 0 0 1.5em;\n          border-left: var(--timeline-width) solid $greyborder;\n        }\n\n        ul {\n          margin-top: 0;\n          padding-left: 1rem;\n\n          li {\n            list-style-type: disc;\n          }\n        }\n      }\n    }\n\n    &[data-source='audit'] {\n      padding-left: 118px;\n\n      .alpaca-user {\n        left: 78px;\n\n        img {\n          width: 24px;\n          height: 24px;\n        }\n      }\n\n      .alpaca-comment-buttons {\n        top: -8px;\n      }\n\n      .alpaca-comment-content {\n        padding-right: 32px;\n        color: #000;\n\n        .timestamp {\n          color: $greytext;\n        }\n\n        * {\n          display: inline;\n        }\n      }\n    }\n  }\n\n  .alpaca-timeline-item {\n    margin: 18px 0 12px 0;\n\n    &:hover .alpaca-comment-buttons {\n      opacity: 1;\n    }\n\n    .alpaca-comment-header {\n      color: $greytext;\n      gap: $spacegap;\n      padding-right: 6px;\n    }\n\n    &[data-source='human'] {\n      .alpaca-timeline-content {\n        flex-grow: 1;\n      }\n    }\n  }\n\n  .alpaca-comment-body {\n    button.components-button {\n      margin: 0 0 8px 8px;\n    }\n\n    .components-textarea-control__input {\n      padding: 11px 14px;\n    }\n  }\n\n  #alpaca-comments .components-textarea-control__input,\n  .alpaca-timeline-item[data-source='human'] .alpaca-comment-content p,\n  .alpaca-timeline-item[data-source='human'] .alpaca-comment-content li {\n    line-height: 1.5em;\n    margin-top: 0;\n  }\n\n  .alpaca-status-manager {\n    .status-grid {\n      border: 1px solid $greyborder;\n      border-radius: 8px;\n      overflow: hidden;\n      font-size: 14px;\n      max-width: 600px;\n\n      .status-grid-header {\n        display: grid;\n        grid-template-columns: 1fr 150px; // name + actions\n        background: #f7f7f7;\n        border-bottom: 1px solid $greyborder;\n        font-weight: 600;\n\n        .status-grid-cell {\n          padding: 8px 12px;\n        }\n\n        .actions-cell {\n          text-align: right;\n        }\n      }\n\n      .status-grid-body {\n        display: flex;\n        flex-direction: column; // ✅ allows placeholder to insert space\n        min-height: 1px; // prevents collapse when empty\n      }\n\n      .status-grid-row {\n        display: grid;\n        grid-template-columns: 1fr 150px; // name + actions\n        align-items: center;\n        border-bottom: 1px solid $greyborder;\n        background: #fff;\n        transition: background 0.2s;\n\n        &:last-child {\n          border-bottom: none;\n        }\n\n        .status-grid-cell {\n          padding: 8px 12px;\n\n          &.actions-cell {\n            text-align: right;\n            white-space: nowrap;\n          }\n        }\n\n        .status-row-content {\n          gap: $spacegap;\n\n          .drag-handle {\n            cursor: grab;\n            padding: 4px;\n            color: $greytext;\n          }\n        }\n      }\n    }\n\n    .alpaca-actions {\n      display: flex;\n      justify-content: flex-end;\n      gap: 8px;\n      margin-top: 16px;\n    }\n  }\n\n  .alpaca-settings {\n    hr {\n      margin: 2em 0;\n    }\n\n    #alpaca-settings-internal {\n      .components-input-control__container {\n        max-width: 25em;\n      }\n    }\n  }\n\n  .alpaca-align-controls {\n    flex-direction: row;\n    gap: $spacegap;\n  }\n}\n\n@media (width >= 861px) {\n  .wp-admin {\n    #alpaca-board {\n      .alpaca-wrap {\n        flex-direction: row;\n        padding: 10px 0;\n        overflow-x: auto;\n\n        .alpaca-container {\n          flex-shrink: 0;\n        }\n      }\n\n      .alpaca-container {\n        width: 16vw;\n        height: 75vh;\n        display: flex;\n        flex-direction: column;\n\n        &.hidden {\n          width: auto;\n          padding: 0 0 10px;\n\n          .alpaca-container-header {\n            height: 100%;\n            writing-mode: vertical-rl;\n            transform: rotate(180deg);\n\n            h2,\n            input {\n              height: 100%;\n            }\n\n            h2 {\n              margin: 5px 0;\n            }\n\n            input {\n              margin: 5px -1px;\n            }\n          }\n        }\n\n        .alpaca-items {\n          overflow-y: auto;\n        }\n      }\n    }\n  }\n}\n\n@media (width <= 860px) {\n  .wp-admin {\n    #alpaca-board {\n      .alpaca-wrap {\n        flex-direction: column;\n      }\n\n      .alpaca-container {\n        width: calc(100% - 2em);\n        margin-top: 1em;\n        overflow-x: auto;\n        display: flex;\n        flex-direction: column;\n        height: auto;\n\n        .alpaca-items {\n          flex-direction: row;\n          display: flex;\n          gap: $spacegap;\n          overflow-x: auto;\n\n          .alpaca-item {\n            width: 200px;\n            height: 140px;\n            flex-shrink: 0;\n\n            .alpaca-item-assignees {\n              &[data-assignees='1'] {\n                .alpaca-user .alpaca-user-name {\n                  display: none;\n                  padding-left: 0;\n                }\n              }\n            }\n          }\n        }\n\n        &.hidden {\n          width: calc(100% - 2em);\n          padding: 0 10px;\n        }\n      }\n    }\n  }\n}\n"],"names":[],"version":3,"file":"index.css.map"}
